/* Page texts and flags for the language switcher. The chosen language is also
   used for the generated PDF (see TEXTS in core/texts.ts). */
import type { Lang } from "../core/texts";

// simplified flags, 30 x 20
const r = (x: number, y: number, w: number, h: number, c: string) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`;
const h3 = (a: string, b: string, c: string) => r(0, 0, 30, 7, a) + r(0, 6.67, 30, 7, b) + r(0, 13.33, 30, 6.67, c);
const v3 = (a: string, b: string, c: string) => r(0, 0, 10, 20, a) + r(10, 0, 10, 20, b) + r(20, 0, 10, 20, c);
const FLAGS: Record<Lang, string> = {
  sk: h3("#fff", "#0b4ea2", "#ee1c25") +
    '<path d="M7 4.2h7.6v6.6c0 3-1.9 4.6-3.8 5.6C8.9 15.4 7 13.8 7 10.8z" fill="#ee1c25" stroke="#fff" stroke-width=".7"/>' +
    '<path d="M10.3 6h.9v1.2h1.5v.8h-1.5v.9h1.9v.8h-1.9v2.6h-.9V9.7H8.4v-.8h1.9V8H8.8v-.8h1.5z" fill="#fff"/>' +
    '<path d="M7.9 13.4c.6-.9 1.3-1.2 2-.8.5-.6 1.3-.6 1.8 0 .7-.4 1.4-.1 2 .8-1 1.3-2 2.1-2.9 2.6-.9-.5-1.9-1.3-2.9-2.6z" fill="#0b4ea2"/>',
  cs: r(0, 0, 30, 10, "#fff") + r(0, 10, 30, 10, "#d7141a") + '<path d="M0 0l15 10L0 20z" fill="#11457e"/>',
  pl: r(0, 0, 30, 10, "#fff") + r(0, 10, 30, 10, "#dc143c"),
  hu: h3("#ce2939", "#fff", "#477050"),
  de: h3("#000", "#dd0000", "#ffce00"),
  en: r(0, 0, 30, 20, "#012169") +
    '<path d="M0 0l30 20M30 0L0 20" stroke="#fff" stroke-width="4"/>' +
    '<path d="M0 0l30 20M30 0L0 20" stroke="#c8102e" stroke-width="1.4"/>' +
    '<path d="M15 0v20M0 10h30" stroke="#fff" stroke-width="6"/>' +
    '<path d="M15 0v20M0 10h30" stroke="#c8102e" stroke-width="3.4"/>',
  fr: v3("#002395", "#fff", "#ed2939"),
  it: v3("#009246", "#fff", "#ce2b37"),
  es: r(0, 0, 30, 20, "#c60b1e") + r(0, 5, 30, 10, "#ffc400"),
  pt: r(0, 0, 30, 20, "#ff0000") + r(0, 0, 12, 20, "#006600") +
    '<circle cx="12" cy="10" r="4.2" fill="none" stroke="#ffcc00" stroke-width="1.4"/>' +
    '<path d="M10.2 7.6h3.6v3.4c0 1.4-1.8 2.2-1.8 2.2s-1.8-.8-1.8-2.2z" fill="#fff" stroke="#ff0000" stroke-width=".7"/>',
  nl: h3("#ae1c28", "#fff", "#21468b"),
  uk: r(0, 0, 30, 10, "#0057b7") + r(0, 10, 30, 10, "#ffd700"),
};

/** Inner SVG markup of a simplified 30 x 20 flag (static, built in this file). */
export const flagSvg = (lang: Lang) => FLAGS[lang] || "";

